51	/// A package specification for pixi.
52	///
53	/// This type can represent both source and binary packages. Use the
54	/// [`Self::try_into_nameless_match_spec`] method to convert this type into a
55	/// type that only represents binary packages.
56	#[derive(Debug, Clone, Hash, ::serde::Serialize, PartialEq, Eq)]
57	#[serde(untagged)]
58	pub enum PixiSpec {
59	    /// The spec is represented solely by a version string. The package should
60	    /// be retrieved from a channel.
61	    ///
62	    /// This is similar to the `DetailedVersion` variant but with a simplified
63	    /// version spec.
64	    Version(VersionSpec),
65	
66	    /// The spec is represented by a detailed version spec. The package should
67	    /// be retrieved from a channel.
68	    DetailedVersion(DetailedSpec),
69	
70	    /// The spec is represented as an archive that can be downloaded from the
71	    /// specified URL. The package should be retrieved from the URL and can
72	    /// either represent a source or binary package depending on the archive
73	    /// type.
74	    Url(UrlSpec),
75	
76	    /// The spec is represented as a git repository. The package represents a
77	    /// source distribution of some kind.
78	    Git(GitSpec),
79	
80	    /// The spec is represented as a local path. The package should be retrieved
81	    /// from the local filesystem. The package can be either a source or binary
82	    /// package.
83	    Path(PathSpec),
84	}
85	
86	impl Default for PixiSpec {
87	    fn default() -> Self {
88	        PixiSpec::Version(VersionSpec::Any)
89	    }
90	}
91	
92	impl From<VersionSpec> for PixiSpec {
93	    fn from(value: VersionSpec) -> Self {
94	        Self::Version(value)
95	    }
96	}
