98	impl PixiSpec {
99	    /// Convert a [`NamelessMatchSpec`] into a [`PixiSpec`].
100	    pub fn from_nameless_matchspec(
101	        spec: NamelessMatchSpec,
102	        channel_config: &ChannelConfig,
103	    ) -> Self {
104	        if let Some(url) = spec.url {
105	            Self::Url(UrlSpec {
106	                url,
107	                md5: spec.md5,
108	                sha256: spec.sha256,
109	            })
110	        } else if spec.build.is_none()
111	            && spec.build_number.is_none()
112	            && spec.file_name.is_none()
113	            && spec.channel.is_none()
114	            && spec.subdir.is_none()
115	            && spec.md5.is_none()
116	            && spec.sha256.is_none()
117	        {
118	            Self::Version(spec.version.unwrap_or(VersionSpec::Any))
119	        } else {
120	            Self::DetailedVersion(DetailedSpec {
121	                version: spec.version,
122	                build: spec.build,
123	                build_number: spec.build_number,
124	                file_name: spec.file_name,
125	                channel: spec.channel.map(|c| {
126	                    NamedChannelOrUrl::from_str(&channel_config.canonical_name(c.base_url.url()))
127	                        .unwrap()
128	                }),
129	                subdir: spec.subdir,
130	                md5: spec.md5,
131	                sha256: spec.sha256,
132	            })
133	        }
134	    }
