136	    /// Returns true if this spec has a version spec. `*` does not count as a
137	    /// valid version spec.
138	    pub fn has_version_spec(&self) -> bool {
139	        match self {
140	            Self::Version(v) => v != &VersionSpec::Any,
141	            Self::DetailedVersion(v) => v.version.as_ref().is_some_and(|v| v != &VersionSpec::Any),
142	            _ => false,
