47	
48	    fn ensure_trailing_slash(url: &url::Url) -> url::Url {
49	        if url.path().ends_with('/') {
50	            url.clone()
51	        } else {
52	            // Do not use `join` because it removes the last element
53	            format!("{}/", url)
54	                .parse()
55	                .expect("Failed to add trailing slash to URL")
56	        }
57	    }
58	
59	    for (key, value) in config.mirror_map() {
60	        let mut mirrors = Vec::new();
61	        for v in value {
62	            mirrors.push(Mirror {
63	                url: ensure_trailing_slash(v),
64	                no_jlap: false,
65	                no_bz2: false,
66	                no_zstd: false,
67	                max_failures: None,
68	            });
69	        }
70	        internal_map.insert(ensure_trailing_slash(key), mirrors);
71	    }
72	
73	    MirrorMiddleware::from_map(internal_map)
74	}
